// Exercise therapy topics for the Dr. MGR BPT Exercise Therapy I and II papers. Written in Learn Anywhere's own words.
window.LIB_EXTRA = (window.LIB_EXTRA || []).concat([
{
  id:"massage", title:"Therapeutic massage: classification, techniques, effects", subject:"Exercise therapy", region:"Soft tissue", stages:"steps",
  aliases:["massage","effleurage","petrissage","tapotement","friction massage","Cyriax deep transverse friction","soft tissue manipulation"],
  simple:"Massage is the use of the hands to move skin, muscle and other soft tissues in a planned way. Different strokes are used to relax, reduce swelling, loosen tissue or stimulate. It helps comfort and short-term pain but should be combined with exercise.",
  flow:["Assess the tissue, the goal and contraindications","Position, support and drape the patient; use a medium if needed","Start with superficial stroking or effleurage","Progress to petrissage, friction or percussion as the goal needs","Finish with effleurage; usual session 10-30 minutes","Re-assess pain, swelling and range; follow with exercise"],
  exam:[
    {h:"Definition", p:["Massage is the systematic and scientific manipulation of the soft tissues of the body with the hands, for therapeutic purposes such as relaxation, pain relief, reduction of oedema and mobilisation of tissue."]},
    {h:"Classification", p:["Stroking manipulations: effleurage (pressure towards the heart, along venous and lymph flow) and superficial stroking (light, any direction).","Pressure (petrissage) manipulations: kneading, picking up, wringing, skin rolling; frictions (circular and deep transverse).","Percussion (tapotement): hacking, clapping (cupping), beating, pounding, tapping.","Vibration and shaking: fine trembling or coarse shaking movements, often used over the chest."]},
    {h:"Technique and dosage", p:["Patient fully supported and relaxed, part elevated for oedema; therapist uses walk-standing or stride-standing to use body weight.","Effleurage: slow rhythmic strokes ending at a lymph node group (axillary, inguinal), pressure only in the centripetal direction.","Deep transverse friction (Cyriax): across the fibres of the tendon or ligament, tissue on stretch for tendons, for about 10 minutes after numbness sets in, 2-3 times a week.","A general session lasts about 10-30 minutes; progress pressure as tolerated."]},
    {h:"Effects", p:["Mechanical: aids venous and lymphatic return, mobilises adhesions, loosens secretions (percussion, vibration).","Physiological: local hyperaemia, warmth, temporary reduction of muscle tone.","Neurological: pain relief by gate control, sedation with slow strokes, stimulation with brisk percussion.","Psychological: relaxation, comfort and reduced anxiety."]},
    {h:"Contraindications and precautions", p:["Deep vein thrombosis or thrombophlebitis (risk of embolus), acute inflammation, local infection, malignancy at the site.","Open wounds, skin disease, burns, recent fracture, myositis ossificans, haemophilia or anticoagulant therapy with bruising.","Over varicose veins and areas of reduced sensation, use only light pressure or avoid."]},
    {h:"Conclusion", p:["Massage is a useful adjunct for pain, oedema and relaxation, but evidence for lasting benefit is low, so it should support active exercise rather than replace it."]}
  ],
  tip:"Make a classification tree with four branches (stroking, pressure, percussion, vibration) and draw arrows showing effleurage strokes ending at the axillary or inguinal nodes.",
  evidence:[["Massage for low back pain","Small short-term pain relief; low-quality evidence","Low"],["Deep transverse friction for lateral elbow or knee tendinitis","No clear benefit over other treatment","Insufficient"],["Manual lymphatic drainage with compression for lymphoedema","Small extra benefit at best","Low"]],
  evidenceSource:"Cochrane reviews (Furlan et al. 2015; Loew et al. 2014)",
  outcomes:[["NPRS or VAS","Pain intensity"],["Limb girth or volume","Oedema"],["Goniometry","Range of motion after soft tissue work"]],
  recent:["The 2015 Cochrane review on massage for low back pain concluded that benefits are mostly short term and the evidence quality is low."],
  mnemonic:{word:"Every Physio Feels The Vibes", items:[["E","Effleurage"],["P","Petrissage (kneading, picking up, wringing, skin rolling)"],["F","Friction"],["T","Tapotement (percussion)"],["V","Vibration and shaking"]], extra:"Effleurage always moves towards the heart."},
  example:"A 60-year-old woman in Coimbatore has a swollen ankle three weeks after cast removal for a fracture. With the leg elevated, effleurage towards the inguinal nodes and kneading of the calf are given for 15 minutes, followed by active ankle pumps.",
  flags:["Calf pain, warmth and swelling: suspect DVT, do not massage","Local malignancy, infection or open wound","Bleeding disorders or heavy bruising on anticoagulants"],
  viva:[["In which direction is effleurage given?","Centripetally, towards the heart, ending at a lymph node group."],["Who popularised deep transverse friction?","James Cyriax."],["Name two percussion manipulations.","Hacking and clapping (also beating, pounding)."]],
  refs:[{b:"cashMed",ch:"Massage and soft tissue techniques"},{c:"Furlan AD, Giraldo M, Baskwill A, Irvin E, Imamura M. Massage for low-back pain. Cochrane Database Syst Rev. 2015;(9):CD001929.", q:"Furlan massage for low-back pain Cochrane 2015"},{c:"Loew LM, Brosseau L, et al. Deep transverse friction massage for treating lateral elbow or lateral knee tendinitis. Cochrane Database Syst Rev. 2014;(11):CD003528.", q:"deep transverse friction massage tendinitis Cochrane"}],
  keywords:"therapeutic massage techniques effects",
  mcq:[["Kneading, picking up and wringing are classified as:",["Stroking manipulations","Pressure (petrissage) manipulations","Percussion manipulations","Vibrations"],1,"They compress and lift the soft tissues, so they are petrissage."],["Massage is absolutely contraindicated in:",["Chronic low back pain","Deep vein thrombosis","Healed scar","Muscle tightness"],1,"Massage may dislodge a thrombus and cause pulmonary embolism."]]
},
{
  id:"traction", title:"Cervical and lumbar traction", subject:"Exercise therapy", region:"Spine", stages:"steps",
  aliases:["spinal traction","cervical traction","lumbar traction","pelvic traction","mechanical traction","intermittent traction","disc prolapse traction"],
  simple:"Traction is a pulling force applied along the spine to separate the vertebrae and stretch soft tissues. It is given by machine, by hand or by body position. It may ease nerve root pain for some people, but on its own it has weak evidence.",
  flow:["Screen for contraindications and red flags","Choose cervical or lumbar, static or intermittent","Position: neck flexed 20-30 degrees or hips and knees flexed","Start with low force and increase in later sessions","Treat 10-20 minutes, monitoring symptoms throughout","Release slowly, rest, re-assess, and add exercise"],
  exam:[
    {h:"Definition", p:["Traction is a mechanical force applied to the body to separate joint surfaces and elongate surrounding soft tissues, given manually, mechanically, by gravity (inversion) or by body positioning."]},
    {h:"Types", p:["By mode: continuous (hours, low force, e.g. bed traction), sustained or static (20-30 minutes), intermittent (hold and relax cycles, e.g. 30-60 seconds on, 10-20 seconds off).","By method: mechanical (motorised unit), manual, positional, gravity-assisted, self-traction (over-door unit for the neck)."]},
    {h:"Effects", p:["Separation of vertebral bodies and facet joints, widening of the intervertebral foramen, possible reduction of disc protrusion by lowered intradiscal pressure.","Stretching of muscles and ligaments, reduced muscle spasm, and pain relief through mechanoreceptor stimulation."]},
    {h:"Dosage and parameters", p:["Cervical: supine, neck flexed about 20-30 degrees (more flexion targets lower levels). Start low (about 3-4.5 kg) for spasm and pain; joint separation usually needs about 9-13 kg.","Lumbar: supine with hips and knees flexed (90-90) to flatten the lordosis, on a split table to remove friction. Start at about 25% of body weight; vertebral separation needs about 50% of body weight.","Time: 10-20 minutes for intermittent, shorter (about 10 minutes) for static disc protocols; daily to 3 times a week, review after 3-6 sessions."]},
    {h:"Indications", p:["Nerve root impingement from disc protrusion or foraminal narrowing, facet joint hypomobility, muscle spasm, cervical radiculopathy (as part of an exercise programme)."]},
    {h:"Contraindications and precautions", p:["Malignancy, infection (tuberculosis of spine), osteoporosis, acute fracture or ligamentous instability, spinal cord compression, rheumatoid arthritis or Down syndrome (atlanto-axial instability), vertebrobasilar insufficiency.","Lumbar: pregnancy, aortic aneurysm, hiatus hernia, uncontrolled hypertension or cardiac or respiratory disease (harness), claustrophobia, TMJ problems with chin halter for the neck.","Stop if peripheral symptoms increase (peripheralise)."]}
  ],
  tip:"Draw the patient supine with the neck in 20-30 degrees flexion and the rope leading to the unit, and a second figure of lumbar traction in 90-90 on a split table. Label force and angle.",
  evidence:[["Lumbar traction for low back pain with or without sciatica","No better than sham or other treatment","Moderate (against routine use)"],["Cervical mechanical traction for neck pain","Insufficient evidence of benefit","Low"],["Exercise plus traction for cervical radiculopathy","Lower disability at longer follow-up than exercise alone in one RCT","Low-moderate"]],
  evidenceSource:"Cochrane reviews (Wegner et al. 2013; Graham et al. 2008) and Fritz et al. JOSPT 2014",
  outcomes:[["Neck Disability Index","Neck-related disability"],["Oswestry Disability Index","Low back disability"],["Centralisation of symptoms","Response of radicular pain during and after traction"]],
  recent:["Fritz et al. (JOSPT 2014) found that adding mechanical or over-door traction to exercise gave better long-term outcomes in cervical radiculopathy, so traction is now taught as an add-on, not a stand-alone treatment."],
  mnemonic:{word:"MOVIES", items:[["M","Malignancy"],["O","Osteoporosis"],["V","Vertebrobasilar insufficiency"],["I","Infection (spinal TB)"],["E","Early fracture or instability"],["S","Spinal cord compression"]], extra:"Lumbar separation needs about half the body weight; start with a quarter."},
  example:"A 42-year-old bank cashier in Madurai has C6 radicular pain into the thumb. Intermittent cervical traction at 25 degrees flexion, starting at 4 kg for 15 minutes, is added to deep neck flexor and nerve mobility exercises.",
  flags:["Dizziness, nystagmus or visual disturbance during cervical traction (vertebrobasilar insufficiency): stop","Bilateral leg symptoms, saddle anaesthesia or bladder change: cauda equina, urgent referral","Increasing or spreading limb pain or weakness during treatment"],
  viva:[["How much force is needed for lumbar vertebral separation?","About 50% of body weight, starting with about 25% for the first session."],["Why is the neck flexed during cervical traction?","Flexion of about 20-30 degrees opens the posterior structures and intervertebral foramina."],["Why use a split table for lumbar traction?","To eliminate friction of the lower body, which would otherwise absorb much of the pull."]],
  refs:[{b:"cameron",ch:"Traction"},{c:"Wegner I, Widyahening IS, van Tulder MW, et al. Traction for low-back pain with or without sciatica. Cochrane Database Syst Rev. 2013;(8):CD003010.", q:"Wegner traction low-back pain sciatica Cochrane"},{c:"Graham N, Gross A, Goldsmith CH, et al. Mechanical traction for neck pain with or without radiculopathy. Cochrane Database Syst Rev. 2008;(3):CD006408.", q:"mechanical traction neck pain radiculopathy Cochrane"},{c:"Fritz JM, Thackeray A, Brennan GP, Childs JD. Exercise only, exercise with mechanical traction, or exercise with over-door traction for patients with cervical radiculopathy. J Orthop Sports Phys Ther. 2014;44(2):45-57.", q:"Fritz cervical radiculopathy traction exercise randomized 2014"}],
  keywords:"cervical lumbar spinal traction",
  mcq:[["The initial force usually recommended for lumbar traction is about:",["5% of body weight","25% of body weight","75% of body weight","100% of body weight"],1,"Start at about a quarter of body weight; separation needs about half."],["Which is a contraindication to cervical traction?",["Cervical spondylosis","Rheumatoid arthritis with atlanto-axial instability","Muscle spasm","Radicular pain"],1,"Traction can worsen upper cervical instability and threaten the cord."]]
},
{
  id:"stretching", title:"Stretching: types, principles and dosage", subject:"Exercise therapy", region:"Muscle", stages:"steps",
  aliases:["stretching","static stretch","ballistic stretch","PNF stretching","hold-relax","contract-relax","flexibility exercise","contracture"],
  simple:"Stretching is any method that lengthens shortened soft tissue to gain range of movement. It can be held still (static), moved through (dynamic), bounced (ballistic) or combined with muscle contraction (PNF). A short hold repeated regularly is enough for healthy muscle; true contractures need long, low-load stretch.",
  flow:["Identify the restricting tissue and cause of tightness","Warm the tissue with light activity or heat","Stabilise the proximal segment, stretch the distal one","Apply low force, slow, to a feeling of tension","Hold 15-30 seconds, 2-4 repetitions, most days","Strengthen in the new range and re-measure"],
  exam:[
    {h:"Definition", p:["Stretching is a therapeutic manoeuvre that elongates shortened or hypomobile soft tissues (muscle, tendon, fascia, capsule) to increase range of motion.","Related terms: flexibility (ability to move through full range), contracture (adaptive shortening that limits range), tightness (mild loss of muscle extensibility)."]},
    {h:"Types", p:["Static: held at end range; passive (by therapist or device) or active (self-stretch).","Ballistic: rapid bouncing; risky because it triggers the stretch reflex, avoided in rehabilitation.","Dynamic: controlled active movements through range, used in warm-up.","PNF stretching: hold-relax, contract-relax, and hold-relax with agonist contraction.","Mechanical: prolonged low-load stretch using splints, serial casting or dynamic orthoses."]},
    {h:"Neurophysiology and tissue response", p:["Muscle spindle: quick stretch causes reflex contraction; slow stretch avoids it.","Golgi tendon organ: tension from contraction causes autogenic inhibition (basis of hold-relax).","Reciprocal inhibition: contracting the agonist relaxes the antagonist being stretched.","Connective tissue: elastic then plastic deformation, creep and stress relaxation; lasting gain needs repeated, prolonged low-load stretch."]},
    {h:"Principles and dosage", p:["Warm up, place the patient in a stable comfortable position, stabilise proximally, move slowly to the point of tightness.","Intensity: low force, tension not pain. Hold 15-30 seconds (30-60 seconds in older adults), 2-4 repetitions, total about 60 seconds per muscle, at least 2-3 days a week (ACSM).","For contractures, hours of positioning or serial casting is needed rather than brief holds.","Follow with active exercise in the gained range so it can be controlled."]},
    {h:"Contraindications and precautions", p:["Bony block, recent fracture or unhealed tissue, acute inflammation or infection, haematoma, sharp pain with stretch, hypermobility.","Do not stretch shortening that gives useful function, such as finger flexor tightness for tenodesis grip in tetraplegia.","Care in osteoporosis, long-term steroids, and after prolonged immobilisation."]},
    {h:"Conclusion", p:["Stretching improves flexibility in healthy tissue when dosed correctly, but evidence that it reverses established contractures is weak, so it should be combined with strengthening and functional training."]}
  ],
  tip:"Draw a muscle with the spindle and Golgi tendon organ labelled, and show arrows for autogenic and reciprocal inhibition. Add a small table comparing static, ballistic, dynamic and PNF stretches.",
  evidence:[["Static hamstring stretch of 30 seconds","As effective as 60 seconds and better than 15 seconds","Moderate"],["Stretch for treating or preventing contracture (under 6 months)","No clinically important effect on joint mobility","High (against expecting benefit)"],["Long static stretch just before power or sprint activity","Small reduction in performance, mainly with holds over 60 seconds","Moderate"]],
  evidenceSource:"Bandy and Irion 1994; Harvey et al. Cochrane 2017; Behm et al. 2016",
  outcomes:[["Goniometry","Joint range of motion"],["Sit and reach test","Hamstring and low back flexibility"],["Thomas test, Ober test, 90-90 SLR","Specific muscle length"]],
  recent:["The 2017 Cochrane review by Harvey and colleagues showed regular stretching does not produce clinically meaningful change in contractures in people with neurological or other conditions."],
  mnemonic:{word:"SLOW", items:[["S","Stabilise the proximal part"],["L","Low force, no pain"],["O","Over 15-30 seconds hold"],["W","Warm the tissue first"]], extra:"Hold-relax uses the GTO (autogenic inhibition); agonist contraction uses reciprocal inhibition."},
  example:"An 18-year-old college footballer in Salem has tight hamstrings (90-90 test lacking 35 degrees). He is taught a supine static hamstring stretch, 30 seconds x 3, daily, plus hold-relax with a partner after training.",
  flags:["Sharp pain or a bony end feel: stop, the limit is not soft tissue","Recently healed fracture or tendon repair","Joint hypermobility or instability"],
  viva:[["Why is ballistic stretching avoided in rehabilitation?","Quick bouncing triggers the muscle spindle stretch reflex and can injure healing tissue."],["What is autogenic inhibition?","Relaxation of a muscle after it contracts, mediated by the Golgi tendon organ, used in hold-relax."],["How long should a static stretch be held?","About 15-30 seconds, repeated 2-4 times."]],
  refs:[{b:"kisner",ch:"Stretching for impaired mobility"},{c:"Bandy WD, Irion JM. The effect of time on static stretch on the flexibility of the hamstring muscles. Phys Ther. 1994;74(9):845-850.", q:"Bandy Irion time static stretch hamstring 1994"},{c:"Harvey LA, Katalinic OM, Herbert RD, et al. Stretch for the treatment and prevention of contractures. Cochrane Database Syst Rev. 2017;(1):CD007455.", q:"Harvey stretch contracture Cochrane 2017"},{b:"acsm",ch:"Flexibility exercise"}],
  keywords:"stretching types dosage PNF",
  mcq:[["Hold-relax stretching mainly relies on:",["Stretch reflex","Autogenic inhibition","Reciprocal innervation of the agonist","Gravity"],1,"The isometric contraction of the tight muscle activates the Golgi tendon organ, which inhibits it."],["Recommended hold for static stretching in a healthy young adult is:",["2-5 seconds","15-30 seconds","5 minutes","30 minutes"],1,"Holds of about 30 seconds give most of the gain."]]
},
{
  id:"coordination", title:"Coordination exercises and Frenkel's exercises", subject:"Exercise therapy", region:"Nervous system", stages:"steps",
  aliases:["Frenkel exercises","coordination","incoordination","ataxia exercises","tabes dorsalis","cerebellar ataxia","sensory ataxia"],
  simple:"Coordination is smooth, accurate, well-timed movement. When it is lost (ataxia), movements become jerky and miss the target. Frenkel's exercises teach the patient to use their eyes and attention to replace lost position sense, starting easy in lying and progressing to walking.",
  flow:["Find the cause: cerebellar or sensory (posterior column) ataxia","Test non-equilibrium and equilibrium coordination","Teach Frenkel principles: concentration, precision, repetition","Progress lying, sitting, standing, then walking","Move from wide, slow, simple to small, varied, complex","Re-test with SARA or coordination tests and reduce visual cues"],
  exam:[
    {h:"Definition", p:["Coordination is the ability to produce smooth, accurate and controlled movement through correct timing, sequencing and grading of muscle activity.","Incoordination (ataxia) results from lesions of the cerebellum, posterior columns or sensory nerves, or the vestibular system."]},
    {h:"Causes and features", p:["Cerebellar ataxia: dysmetria, intention tremor, dysdiadochokinesia, rebound phenomenon, hypotonia, wide-based gait, not much helped by vision.","Sensory ataxia (tabes dorsalis, subacute combined degeneration, neuropathy): loss of joint position sense, stamping gait, watches the feet, worse with eyes closed (Romberg positive)."]},
    {h:"Assessment", p:["Non-equilibrium tests: finger-to-nose, finger-to-therapist's finger, heel-to-shin, rapid alternating movements, drawing a circle, rebound test.","Equilibrium tests: Romberg, tandem walking, standing on one leg, walking with change of direction.","Scales: Scale for Assessment and Rating of Ataxia (SARA), Berg Balance Scale."]},
    {h:"Frenkel's exercises", p:["Developed by Heinrich Frenkel in the late 1800s for tabes dorsalis; uses vision to substitute for lost proprioception.","Principles: concentration of attention, precision of movement, repetition until easy. Movements are done slowly to a count.","Progression: lying (heel slides, hip abduction, placing the heel at marked points) -> sitting (marking footprints, standing up and sitting down to a count) -> standing (stepping to marks) -> walking along lines and between parallel bars.","Dosage: each movement about 4 times, short sessions several times a day with rest between to avoid fatigue; from simple to complex, wide to narrow range, slow to varied speed."]},
    {h:"Other coordination training", p:["Cerebellar: rhythmic stabilisation and slow reversals (PNF), weight cuffs or weighted walkers to damp tremor, task-specific practice, balance and gait training.","Sensory: vision and mirror feedback, then gradual removal of visual cues; safety training for dark areas."]},
    {h:"Conclusion", p:["Frenkel's method works best for sensory ataxia. For cerebellar ataxia, intensive coordinative and balance training has moderate evidence of benefit."]}
  ],
  tip:"Draw a floor plan of footprints and lines used for Frenkel walking, and a supine figure with heel targets on the opposite shin. Write the three principles beside it.",
  evidence:[["Intensive coordinative training in degenerative cerebellar ataxia","Improved ataxia scores and gait","Moderate (small trials)"],["Video game based coordination training in children with ataxia","Reduced ataxia symptoms","Low"],["Frenkel's exercises for sensory ataxia","Long-standing clinical use, few controlled trials","Low"]],
  evidenceSource:"Ilg et al. Neurology 2009 and 2012; standard texts",
  outcomes:[["SARA","Severity of ataxia"],["Berg Balance Scale","Balance and fall risk"],["Timed finger-to-nose or 9-hole peg test","Upper-limb coordination"]],
  recent:["Ilg et al. (Neurology 2012) showed that whole-body video game training improved ataxia scores in children with degenerative ataxia, supporting home-based exergames."],
  mnemonic:{word:"CPR", items:[["C","Concentration of attention"],["P","Precision"],["R","Repetition"]], extra:"Progress Lying -> Sitting -> Standing -> Walking."},
  example:"A 55-year-old man in Vellore with vitamin B12 deficiency has a stamping gait and falls in the dark. Romberg is positive. Frenkel's exercises in supine and sitting are started with visual feedback, then walking on marked floor lines.",
  flags:["Sudden new ataxia with headache or vomiting: possible cerebellar stroke, urgent referral","Falls during standing exercises: guard closely","Fatigue worsens coordination: rest between repetitions"],
  viva:[["For which condition did Frenkel design his exercises?","Tabes dorsalis (sensory ataxia from posterior column damage)."],["What is dysdiadochokinesia?","Inability to perform rapid alternating movements, a cerebellar sign."],["Which ataxia worsens on closing the eyes?","Sensory ataxia (Romberg positive)."]],
  refs:[{b:"osullivan",ch:"Examination of coordination"},{b:"umphred",ch:"Cerebellar dysfunction"},{c:"Ilg W, Synofzik M, Brotz D, et al. Intensive coordinative training improves motor performance in degenerative cerebellar disease. Neurology. 2009;73(22):1823-1830.", q:"Ilg intensive coordinative training cerebellar disease Neurology 2009"}],
  keywords:"Frenkel exercises coordination ataxia",
  mcq:[["Frenkel's exercises mainly use which system to compensate for lost proprioception?",["Vestibular","Vision","Auditory","Cerebellar"],1,"The patient watches the limb and targets to replace position sense."],["Which is a non-equilibrium coordination test?",["Romberg test","Tandem walking","Finger-to-nose test","Single-leg stance"],2,"Non-equilibrium tests are done without standing balance demands."]]
},
{
  id:"balance-training", title:"Balance exercises and balance training", subject:"Exercise therapy", region:"Whole body", stages:"steps",
  aliases:["balance training","postural control","falls prevention","Otago exercise programme","ankle strategy","hip strategy","Berg balance"],
  simple:"Balance is keeping the body's centre of mass over its base of support, still or moving. It depends on vision, the inner ear and sensation from the feet and joints, plus strength and reactions. Balance training challenges these systems step by step to reduce falls.",
  flow:["Find the cause: sensory, motor, cognitive or environmental","Assess with BBS, TUG and single-leg stance","Start static: wide base, firm surface, eyes open","Progress: narrow base, foam, eyes closed, head turns","Add dynamic, reactive and dual-task practice","Dose at least 3 hours a week; re-test and modify home"],
  exam:[
    {h:"Definition", p:["Balance (postural control) is the ability to keep the centre of mass within the base of support, both at rest (static) and during movement (dynamic), and to recover after a disturbance (reactive)."]},
    {h:"Components", p:["Sensory: visual, vestibular and somatosensory inputs, integrated in the CNS.","Motor: strength (especially hip and ankle), range of motion, reaction time.","Strategies: ankle strategy (small, slow sway on a firm surface), hip strategy (larger or faster sway, narrow surface), stepping strategy (when the centre of mass leaves the base).","Anticipatory postural adjustments before voluntary movement; cognitive and attention demands."]},
    {h:"Assessment", p:["Berg Balance Scale (0-56; a score below about 45 suggests increased fall risk), Timed Up and Go (over about 13.5 seconds in community older adults suggests risk), functional reach, single-leg stance, Romberg and sharpened Romberg.","Modified Clinical Test of Sensory Interaction in Balance (foam and eyes closed), BESTest or Mini-BESTest, falls history and home hazards."]},
    {h:"Physiotherapy management and dosage", p:["Progress static balance: wide to narrow base (feet apart, together, semi-tandem, tandem, single leg), firm to foam surface, eyes open to closed, add head turns.","Dynamic: weight shifts, reaching, stepping, walking on lines, turns, obstacles, stairs; reactive: perturbations and stepping practice.","Dual-task practice (talking or counting while walking), Tai Chi, Otago programme (home strength and balance, about 3 times a week, plus walking).","Dose for falls prevention: about 3 hours a week of challenging balance and functional exercise, continued long term, always with safe guarding."]},
    {h:"Precautions", p:["Use a gait belt, parallel bars or a corner; never leave a high-risk patient unattended.","Check for orthostatic hypotension, visual problems, medication side effects and footwear."]},
    {h:"Conclusion", p:["Progressive, challenging balance training reduces falls in older adults and should be combined with strength training and home safety advice."]}
  ],
  tip:"Draw a standing figure with the centre of mass and base of support marked, and three small figures showing ankle, hip and stepping strategies. Add an arrow of progression from easy to hard.",
  evidence:[["Balance and functional exercise in community older adults","Reduces rate of falls by about a quarter","High"],["Tai Chi","Reduces falls","Moderate"],["Multicomponent exercise (balance plus strength)","Reduces falls and fear of falling","Moderate-high"]],
  evidenceSource:"Sherrington et al. Cochrane 2019; World Falls Guidelines 2022",
  outcomes:[["Berg Balance Scale","Static and dynamic balance, fall risk"],["Timed Up and Go","Functional mobility and fall risk"],["Mini-BESTest","Balance systems, including reactive control"],["Falls diary","Number of falls"]],
  recent:["The World Guidelines for Falls Prevention (Montero-Odasso et al., Age and Ageing 2022) recommend progressive balance and strength exercise for older adults at risk of falling."],
  mnemonic:{word:"Eyes, Ears, Feet", items:[["Eyes","Visual input"],["Ears","Vestibular input"],["Feet","Somatosensory input"]], extra:"Strategies in order of growing sway: Ankle, Hip, Step."},
  example:"A 72-year-old retired teacher in Tiruchirappalli has had two falls this year. TUG 16 seconds, BBS 42. She starts semi-tandem and tandem stance near a kitchen counter, sit to stand, and stepping practice, 30 minutes 3 times a week, with home hazard advice.",
  flags:["Sudden dizziness with slurred speech or weakness: possible stroke","Drop in blood pressure on standing (postural hypotension)","Repeated unexplained falls or blackouts: medical review"],
  viva:[["Which three systems give sensory input for balance?","Visual, vestibular and somatosensory."],["When is the hip strategy used?","With larger or faster disturbances, or on a narrow surface."],["What is the maximum score on the Berg Balance Scale?","56."]],
  refs:[{b:"shumway",ch:"Normal postural control and balance"},{b:"osullivan",ch:"Interventions to improve balance"},{c:"Sherrington C, Fairhall NJ, Wallbank GK, et al. Exercise for preventing falls in older people living in the community. Cochrane Database Syst Rev. 2019;(1):CD012424.", q:"Sherrington exercise preventing falls community Cochrane 2019"},{c:"Montero-Odasso M, et al. World guidelines for falls prevention and management for older adults: a global initiative. Age Ageing. 2022;51(9):afac205.", q:"world guidelines falls prevention older adults 2022"}],
  keywords:"balance training falls prevention",
  mcq:[["Balance on a firm surface with a small, slow sway is corrected mainly by:",["Hip strategy","Ankle strategy","Stepping strategy","Suspensory strategy"],1,"Small, slow sway on a firm surface is handled at the ankle."],["Which is the hardest progression for static balance training?",["Feet apart, eyes open","Feet together, eyes open","Tandem stance on foam, eyes closed","Semi-tandem on floor"],2,"Narrow base, unstable surface and no vision is most challenging."]]
},
{
  id:"breathing-exercises", title:"Breathing exercises: diaphragmatic, segmental and pursed-lip", subject:"Exercise therapy", region:"Chest", stages:"steps",
  aliases:["breathing exercises","diaphragmatic breathing","pursed lip breathing","segmental breathing","localised expansion","thoracic expansion exercises","breathing control"],
  simple:"Breathing exercises teach patients to use the diaphragm, open up parts of the lung, and slow their breathing out. Diaphragmatic breathing makes breathing more efficient, segmental breathing helps a collapsed or stiff area expand, and pursed-lip breathing eases breathlessness in COPD.",
  flow:["Assess breathing pattern, chest expansion, SpO2 and dyspnoea","Position relaxed: half lying or high side lying","Teach diaphragmatic breathing with hand on the abdomen","Add segmental expansion with hand pressure over the target area","Teach pursed-lip breathing for exertion and breathlessness","3-4 deep breaths then rest; repeat through the day"],
  exam:[
    {h:"Definition and aims", p:["Breathing exercises are controlled breathing techniques that improve ventilation, re-expand lung tissue, reduce the work of breathing, relieve breathlessness and help clear secretions.","Used in COPD, asthma, after thoracic and abdominal surgery, pleural effusion, and in anxiety-related breathing disorders."]},
    {h:"Diaphragmatic breathing", p:["Patient half lying with knees supported; therapist's hand on the epigastrium just below the costal margin.","Breathe in slowly through the nose so the abdomen rises under the hand, upper chest stays relaxed; breathe out gently and passively.","Progress to sitting, standing, walking and stairs. Avoid forced expiration."]},
    {h:"Segmental (localised) breathing", p:["Hand placed over the area to expand: apical, lateral costal (unilateral or bilateral), or posterior basal.","Firm pressure at the end of expiration, a quick stretch just before inspiration, then the patient breathes in against the hand; pressure is eased as the chest expands.","A 3-second end-inspiratory hold can be added to improve collateral ventilation. Common after thoracotomy, in pleural effusion and atelectasis."]},
    {h:"Pursed-lip breathing", p:["Breathe in through the nose for about 2 counts; breathe out slowly through gently pursed lips for about 4 counts (I:E about 1:2). Expiration is relaxed, not forced.","The back pressure splints the small airways open, reducing air trapping; breathing rate falls, tidal volume and oxygen saturation may improve."]},
    {h:"Dosage and precautions", p:["3-4 deep breaths then return to relaxed breathing to avoid hyperventilation; repeat hourly after surgery, and during activity in COPD.","Precautions: dizziness from hyperventilation, fatigue, pain after surgery (give analgesia first). In severe COPD with a flattened diaphragm, diaphragmatic breathing may increase breathlessness and paradoxical movement, so pursed-lip breathing and positioning are preferred."]},
    {h:"Conclusion", p:["Breathing exercises are part of the active cycle of breathing technique and pulmonary rehabilitation; they work best combined with airway clearance, positioning and exercise training."]}
  ],
  tip:"Draw the patient in half lying with the therapist's hands marked on the epigastrium, lateral costal and apical areas, and an arrow showing the lips pursed with 1:2 inspiration-expiration counts.",
  evidence:[["Breathing exercises in COPD","Improved functional exercise capacity in some trials; no consistent effect on breathlessness","Low-moderate"],["Pursed-lip breathing","Lowers breathing rate and may improve oxygen saturation during exertion","Low-moderate"],["Diaphragmatic breathing in severe COPD","May worsen dyspnoea and chest wall asynchrony","Low"]],
  evidenceSource:"Holland et al. Cochrane 2012; BTS pulmonary rehabilitation guideline 2013",
  outcomes:[["Chest expansion (tape at axilla, xiphisternum)","Thoracic mobility"],["Modified Borg or mMRC","Breathlessness"],["SpO2 and respiratory rate","Gas exchange and breathing pattern"],["6-minute walk test","Functional exercise capacity"]],
  recent:["The BTS guideline on pulmonary rehabilitation (Bolton et al., Thorax 2013) places breathing control within a wider exercise and education programme rather than as a stand-alone treatment."],
  mnemonic:{word:"Smell the rose, blow the candle", items:[["Smell","In through the nose for 2 counts"],["Blow","Out through pursed lips for 4 counts"],["1:2","Inspiration to expiration ratio"]], extra:"Segmental breathing: press at end of expiration, quick stretch, breathe into the hand."},
  example:"A 65-year-old former mill worker in Erode with COPD becomes breathless climbing stairs. He is taught pursed-lip breathing timed with steps (in for 2 steps, out for 4) and forward lean sitting for recovery.",
  flags:["Sudden pleuritic chest pain and breathlessness after surgery: suspect pulmonary embolism or pneumothorax","SpO2 dropping below the patient's target range: stop and give oxygen as prescribed","Dizziness or tingling: hyperventilation, return to relaxed breathing"],
  viva:[["Where are the hands placed for diaphragmatic breathing?","Over the epigastrium, just below the anterior costal margin."],["Why does pursed-lip breathing help in COPD?","It creates back pressure that keeps small airways open, reducing air trapping and slowing breathing."],["When is the quick stretch given in segmental breathing?","At the end of expiration, just before inspiration."]],
  refs:[{b:"frownfelter",ch:"Breathing exercises and retraining"},{b:"kisner",ch:"Management of pulmonary conditions"},{c:"Holland AE, Hill CJ, Jones AY, McDonald CF. Breathing exercises for chronic obstructive pulmonary disease. Cochrane Database Syst Rev. 2012;(10):CD008250.", q:"Holland breathing exercises COPD Cochrane 2012"},{c:"Bolton CE, et al. British Thoracic Society guideline on pulmonary rehabilitation in adults. Thorax. 2013;68 Suppl 2:ii1-30.", q:"British Thoracic Society guideline pulmonary rehabilitation 2013"}],
  keywords:"breathing exercises diaphragmatic pursed lip",
  mcq:[["The usual inspiration to expiration ratio taught in pursed-lip breathing is about:",["2:1","1:1","1:2","1:5 with forced blowing"],2,"Expiration is slowed to about twice inspiration, without forcing."],["In segmental breathing, the therapist gives a quick stretch:",["At the start of expiration","At the end of expiration","Mid inspiration","During breath hold"],1,"The stretch just before inspiration facilitates the intercostals and diaphragm."]]
},
{
  id:"crutch-gait", title:"Walking aids and crutch gait patterns", subject:"Exercise therapy", region:"Lower limb", stages:"steps",
  aliases:["crutch walking","axillary crutch","elbow crutch","walking aids","three point gait","four point gait","swing through gait","walker cane"],
  simple:"Walking aids such as canes, crutches and walkers widen the base of support and take weight off a painful or weak leg. The aid must be the right height. Gait patterns (2-point, 3-point, 4-point, swing-to and swing-through) are chosen by how much weight the leg can take and the patient's strength and balance.",
  flow:["Assess weight-bearing status, strength, balance and cognition","Choose the aid: walker, axillary or elbow crutches, cane","Measure and adjust height; check the elbow is flexed 15-30 degrees","Teach the gait pattern in parallel bars first","Teach sit to stand, turning and stairs","Progress the aid and pattern as weight-bearing increases"],
  exam:[
    {h:"Definition and purpose", p:["Walking aids are devices that increase the base of support, improve balance, and reduce load on a lower limb during walking.","Types (most to least support): walker (frame, rollator), axillary crutches, elbow (forearm, Lofstrand) crutches, quadripod and tripod canes, single-point cane."]},
    {h:"Measurement", p:["Axillary crutch standing: tip about 5 cm lateral and 15 cm in front of the foot; top 2-3 finger widths (about 5 cm) below the axilla; handgrip at the greater trochanter or wrist crease with the elbow flexed about 15-30 degrees.","Supine method: anterior axillary fold to a point about 15-20 cm lateral to the heel.","Cane and walker: handle at the greater trochanter or wrist crease, elbow flexed 15-30 degrees. A single cane is held in the hand opposite the affected leg."]},
    {h:"Gait patterns", p:["4-point: crutch, opposite foot, other crutch, other foot. Slow and very stable; bilateral weakness or poor balance.","2-point: one crutch with the opposite foot together, then the other pair. Faster, needs good coordination.","3-point: both crutches and the affected leg together, then the good leg. Used for non or partial weight bearing on one leg.","Swing-to and swing-through: both crutches forward, body swings to or past them. Used in paraplegia with orthoses; needs strong upper limbs.","Weight-bearing grades: NWB, toe-touch, PWB (often guided with a weighing scale), WBAT, FWB."]},
    {h:"Stairs and transfers", p:["Going up: good leg first, then crutches and affected leg. Going down: crutches and affected leg first, then good leg.","Sit to stand: both crutches in the hand on the affected side, push from the chair arm with the other hand."]},
    {h:"Complications and precautions", p:["Crutch palsy (radial nerve compression) from leaning on the axillary pad; teach weight through the hands.","Falls on wet floors, loose rugs, worn rubber tips; check tips and screws. Upper-limb overuse in long-term users."]},
    {h:"Conclusion", p:["The correct aid, height and pattern, taught in the parallel bars and progressed with weight-bearing, gives safe and efficient walking."]}
  ],
  tip:"Draw footprint and crutch-tip sequences for 4-point, 2-point and 3-point gait, numbering each step. Show the crutch position 5 cm lateral and 15 cm anterior to the foot.",
  evidence:[["Cane in the hand opposite the painful hip","Reduces hip abductor demand and joint load","Moderate (biomechanical studies)"],["Partial weight-bearing teaching with bathroom scale","Patients often exceed the prescribed load without feedback","Low-moderate"],["Choice of crutch gait pattern","Based on clinical reasoning, few trials","Low"]],
  evidenceSource:"Biomechanics texts (Neumann) and clinical reviews (Bradley and Hernandez 2011)",
  outcomes:[["Timed Up and Go","Mobility with the aid"],["10-metre walk test","Gait speed"],["Functional Ambulation Category","Level of assistance needed"]],
  recent:["Gait speed is widely promoted as a functional vital sign (Fritz and Lusardi, J Geriatr Phys Ther 2009), and is now routinely recorded when prescribing and progressing aids."],
  mnemonic:{word:"Up with the good, down with the bad", items:[["Up","Good leg first"],["Down","Crutches and bad leg first"],["Cane","Opposite hand to the affected leg"]], extra:"4-point is most stable; swing-through is fastest."},
  example:"A 30-year-old two-wheeler rider in Chennai has an ORIF of the tibia and is non-weight bearing on the right. Axillary crutches are adjusted and he is taught 3-point NWB gait in the parallel bars, then stairs before discharge.",
  flags:["Numbness or weakness of wrist extensors: crutch palsy from axillary pressure","Dizziness or falls during first ambulation","Increasing calf pain or swelling after lower-limb surgery: DVT"],
  viva:[["Which gait pattern is used for a non-weight-bearing leg?","3-point gait (or swing-to or swing-through if able)."],["In which hand is a cane held for a right hip OA?","The left hand."],["What nerve is at risk with axillary crutches?","The radial nerve."]],
  refs:[{b:"osullivan",ch:"Locomotor training and assistive devices"},{b:"neumann",ch:"Hip: cane use and hip abductor force"},{c:"Bradley SM, Hernandez CR. Geriatric assistive devices. Am Fam Physician. 2011;84(4):405-411.", q:"Bradley Hernandez geriatric assistive devices Am Fam Physician"}],
  keywords:"crutch gait patterns walking aids",
  mcq:[["The most stable crutch gait pattern is:",["2-point","4-point","Swing-through","3-point"],1,"Three points are always on the ground in 4-point gait."],["When climbing stairs with crutches, the patient leads with:",["The affected leg","The crutches","The good leg","Both legs together"],2,"Up with the good, down with the bad."]]
},
{
  id:"suspension", title:"Suspension therapy", subject:"Exercise therapy", region:"Whole body", stages:"steps",
  aliases:["suspension therapy","Guthrie-Smith frame","axial suspension","pendular suspension","vertical suspension","sling exercise","gravity eliminated exercise"],
  simple:"Suspension therapy holds a body part up in slings and ropes so the weight of the limb is supported. This lets very weak muscles move it, or lets stiff joints relax and move freely. By changing where the rope is fixed, the movement can be made gravity-free, assisted or resisted.",
  flow:["Assess muscle grade, range and the aim of treatment","Choose the type: axial, vertical or pendular","Place slings at the centre of gravity of each segment","Set the fixation point relative to the joint axis","Exercise: free, assisted or resisted; add springs if needed","Progress to gravity-resisted and functional exercise"],
  exam:[
    {h:"Definition", p:["Suspension therapy is the use of slings, ropes, pulleys and springs attached to an overhead frame to support a body part, eliminating the effect of gravity so it can be exercised, mobilised or relaxed."]},
    {h:"Equipment", p:["Overhead frame (Guthrie-Smith frame) or suspension cage, slings (single and double, wide and narrow), ropes, S-hooks, single and double pulleys, springs, wooden cleats or pegs, and a firm plinth."]},
    {h:"Types (by fixation point)", p:["Axial suspension: the fixation point is directly above the axis of the joint; the limb moves in a horizontal arc with gravity eliminated, so movement is neither assisted nor resisted. Used for MMT grade 2 muscles.","Vertical suspension: the fixation point is directly above the centre of gravity of the segment; it simply supports the part, used for relaxation and comfort.","Pendular suspension: the fixation point is displaced from the joint axis; the limb swings like a pendulum. When displaced in the direction of the movement the movement is assisted; when displaced in the opposite direction it is resisted."]},
    {h:"Uses and dosage", p:["Relaxation and pain relief, mobilisation of stiff joints (rhythmic pendular swings), muscle re-education for grade 1-2 muscles, strengthening by adding springs or displacing the pivot, and support for other treatment.","A typical session is 15-20 minutes; progress by moving the pivot, adding springs, increasing range and repetitions, then to gravity-resisted exercise."]},
    {h:"Precautions", p:["Check ropes, hooks and slings for wear; slings must not compress nerves or vessels.","Avoid in acute inflammation where movement is not wanted, unhealed fractures without support, and in patients who become anxious or dizzy in slings."]},
    {h:"Conclusion", p:["Suspension is a simple way to give gravity-eliminated or graded exercise. It is used less often now, though sling-based exercise (such as Redcord) is a modern version; evidence that it beats other exercise is limited."]}
  ],
  tip:"Draw three small diagrams of the hip in side lying with the rope fixed directly above the joint (axial), above the limb's centre of gravity (vertical), and displaced (pendular), with arrows labelled assisted and resisted.",
  evidence:[["Sling exercise for chronic low back pain","No clear advantage over motor control or general exercise","Moderate"],["Suspension for gravity-eliminated exercise in weak muscles","Established clinical practice, few trials","Low"]],
  evidenceSource:"Unsgaard-Tondel et al. Phys Ther 2010; standard exercise therapy texts",
  outcomes:[["Manual muscle testing (Oxford grades)","Muscle strength progression"],["Goniometry","Range of motion"],["Oswestry Disability Index","Function when used for back pain"]],
  recent:["A randomised trial (Unsgaard-Tondel et al., Phys Ther 2010) found sling exercise was no better than general exercise for chronic low back pain, so it is one option among many."],
  mnemonic:{word:"AVP", items:[["A","Axial: above the joint, gravity eliminated"],["V","Vertical: above the centre of gravity, support only"],["P","Pendular: displaced pivot, assisted or resisted"]], extra:"Pivot displaced towards the movement assists; away from it resists."},
  example:"A 25-year-old man in Tirunelveli recovering from a femoral nerve injury has grade 2 quadriceps. In side lying with axial suspension of the leg, he practises knee extension through full range without gravity, 3 sets of 10.",
  flags:["Worn ropes or loose hooks: risk of sudden fall of the limb","Sling pressure over the common peroneal nerve or popliteal fossa","Patient anxiety, dizziness or pain during swinging"],
  viva:[["What is axial suspension?","The fixation point is directly over the joint axis so movement is horizontal and gravity eliminated."],["How can suspension make a movement resisted?","Displace the fixation point in the direction opposite to the movement, or add a spring."],["Which muscle grade is most suited to suspension?","Grade 1-2 (poor) muscles."]],
  refs:[{b:"kisner",ch:"Range of motion: assisted and self-assisted exercise"},{b:"cashMed",ch:"Exercise therapy equipment and suspension"},{c:"Unsgaard-Tondel M, Fladmark AM, Salvesen O, Vasseljen O. Motor control exercises, sling exercises, and general exercises for patients with chronic low back pain: a randomized controlled trial with 1-year follow-up. Phys Ther. 2010;90(10):1426-1440.", q:"Unsgaard-Tondel sling exercise chronic low back pain"}],
  keywords:"suspension therapy axial pendular",
  mcq:[["In axial suspension the fixation point is:",["Above the centre of gravity of the limb","Directly above the joint axis","Displaced towards the movement","At the foot of the bed"],1,"This gives a horizontal arc with gravity eliminated."],["Suspension is most useful for muscles of grade:",["0","1-2","4","5"],1,"Weak muscles that cannot work against gravity benefit most."]]
},
{
  id:"hydrotherapy", title:"Hydrotherapy: principles and therapeutic pool exercise", subject:"Exercise therapy", region:"Whole body", stages:"steps",
  aliases:["hydrotherapy","aquatic therapy","pool therapy","buoyancy","Bad Ragaz","Halliwick","hydrostatic pressure"],
  simple:"Hydrotherapy is exercise in a warm pool. Water holds up body weight (buoyancy), squeezes the body evenly (hydrostatic pressure) and resists fast movement (viscosity). This lets people with pain, weakness or joint problems move more easily and safely.",
  flow:["Screen for contraindications, wounds, continence and fear of water","Set water at about 33-36 degrees Celsius","Use buoyancy: assist, support or resist movement","Use speed, turbulence and floats to grade resistance","Treat about 20-30 minutes, rest and rehydrate afterwards","Progress to land-based exercise and function"],
  exam:[
    {h:"Definition", p:["Hydrotherapy (aquatic therapy) is the use of water, mainly a heated therapeutic pool, for exercise and rehabilitation, using the physical properties of water to assist, support or resist movement."]},
    {h:"Physical principles", p:["Buoyancy (Archimedes): an upward force equal to the weight of water displaced. Immersion to the waist removes about half of body weight, to the xiphisternum about 60-75%, to the neck about 90%. Movement towards the surface is assisted, parallel is supported, towards the floor is resisted.","Relative density: the human body is slightly less dense than water (about 0.95-0.97), so most people float.","Hydrostatic pressure (Pascal): equal pressure at any depth, increasing with depth; helps venous return and reduce oedema, but loads the heart and chest.","Viscosity, turbulence and drag: resistance increases with speed and frontal area; used to grade strengthening.","Thermal effects of warm water: muscle relaxation, pain relief, increased circulation. Refraction makes limbs look bent, so teach by feel."]},
    {h:"Techniques", p:["Buoyancy-assisted, buoyancy-supported and buoyancy-resisted exercise with floats, bats and paddles.","Bad Ragaz ring method: patient supported by floats, therapist gives resistance in PNF-like patterns.","Halliwick concept: ten-point programme for water confidence, balance and swimming, widely used for children with disability.","Deep water running, walking in water, Watsu and Ai Chi for relaxation."]},
    {h:"Dosage and indications", p:["Water temperature about 33-36 degrees Celsius; sessions start at about 20 minutes and progress to 30-40 minutes, 2-3 times a week.","Indications: osteoarthritis, rheumatoid arthritis, ankylosing spondylitis, low back pain, post-operative orthopaedic rehabilitation, neurological conditions, cerebral palsy."]},
    {h:"Contraindications and precautions", p:["Contraindications: open wounds, skin or wound infections, fever, uncontrolled epilepsy, severe or unstable cardiac or respiratory disease, faecal incontinence, recent radiotherapy to the skin, contagious conditions.","Precautions: fear of water, low or high blood pressure, diabetes, tracheostomy, urinary catheter, reduced sensation, fatigue and dehydration after warm immersion; always supervise entry and exit."]},
    {h:"Conclusion", p:["Hydrotherapy allows early, low-load exercise. In knee and hip osteoarthritis it gives small short-term gains in pain and function, similar to land exercise, and is especially useful for patients who cannot tolerate land exercise."]}
  ],
  tip:"Draw a figure standing in a pool with water levels marked at the waist, xiphisternum and neck with the percentage of weight offloaded at each. Add arrows showing buoyancy-assisted, supported and resisted movement of the arm.",
  evidence:[["Aquatic exercise for knee and hip osteoarthritis","Small short-term improvement in pain, function and quality of life","Moderate"],["Aquatic exercise compared with land exercise in OA","Similar benefits","Moderate"],["Halliwick-based programmes in children with disability","Improved water skills and confidence","Low"]],
  evidenceSource:"Bartels et al. Cochrane 2016 and clinical reviews",
  outcomes:[["WOMAC","Pain, stiffness and function in OA"],["NPRS","Pain"],["Gait speed and TUG on land","Transfer of gains to function"]],
  recent:["The 2016 Cochrane update on aquatic exercise for knee and hip osteoarthritis found small, short-term benefits, supporting it as an option rather than a superior treatment."],
  mnemonic:{word:"BHVT", items:[["B","Buoyancy: assists, supports, resists"],["H","Hydrostatic pressure: oedema, venous return"],["V","Viscosity and turbulence: resistance with speed"],["T","Thermal: relaxation and pain relief"]], extra:"Towards the surface is assisted, towards the floor is resisted."},
  example:"A 58-year-old homemaker in Coimbatore with bilateral knee OA cannot walk 200 metres on land. She starts chest-deep pool walking and buoyancy-assisted knee flexion and extension in water at 34 degrees Celsius, 30 minutes twice a week.",
  flags:["Chest pain or breathlessness in the pool: hydrostatic pressure increases cardiac load","Seizure risk in uncontrolled epilepsy","Open wounds or infections: cross-infection"],
  viva:[["State Archimedes' principle.","A body immersed in a fluid experiences an upthrust equal to the weight of fluid displaced."],["What is the usual temperature of a therapeutic pool?","About 33-36 degrees Celsius."],["Name a hydrotherapy technique based on PNF patterns.","Bad Ragaz ring method."]],
  refs:[{b:"cameron",ch:"Hydrotherapy"},{b:"kisner",ch:"Aquatic exercise"},{c:"Bartels EM, Juhl CB, Christensen R, et al. Aquatic exercise for the treatment of knee and hip osteoarthritis. Cochrane Database Syst Rev. 2016;(3):CD005523.", q:"Bartels aquatic exercise knee hip osteoarthritis Cochrane 2016"}],
  keywords:"hydrotherapy aquatic therapy buoyancy",
  mcq:[["Movement of a limb towards the surface of the water is:",["Resisted by buoyancy","Assisted by buoyancy","Unaffected by buoyancy","Resisted by hydrostatic pressure"],1,"Buoyancy acts upwards, helping movement towards the surface."],["The Halliwick concept is mainly used to:",["Strengthen with PNF patterns","Teach water confidence and swimming to people with disability","Apply traction in water","Treat open wounds"],1,"Halliwick uses a ten-point programme for water confidence and balance."]]
},
{
  id:"pathological-gaits", title:"Pathological gaits (antalgic, Trendelenburg, high-stepping, hemiplegic, scissoring, festinating, ataxic)", subject:"Exercise therapy", region:"Lower limb", stages:"steps",
  aliases:["abnormal gait","antalgic gait","Trendelenburg gait","steppage gait","foot drop gait","circumduction","scissoring gait","festinating gait","ataxic gait"],
  simple:"A pathological gait is an abnormal walking pattern caused by pain, weakness, deformity or a nervous system problem. Each pattern has a typical look, so careful observation tells you the cause. Treatment targets the cause and may add orthoses, aids and gait training.",
  flow:["Observe the patient from the front, side and back","Identify the pattern in stance and swing phases","Link the pattern to its cause: pain, weakness, tone, sensation","Confirm with specific tests (Trendelenburg, MMT, tone, Romberg)","Treat the cause: strengthen, stretch, orthosis, aid, cueing","Re-train gait and measure speed and function"],
  exam:[
    {h:"Definition", p:["Pathological gait is any deviation from the normal gait cycle in timing, joint motion, base of support or symmetry, resulting from pain, muscle weakness, joint deformity, abnormal tone or loss of coordination or sensation."]},
    {h:"Musculoskeletal and nerve gaits", p:["Antalgic: short stance phase on the painful leg, so the good leg takes a quick short step; with hip pain the trunk leans over the painful hip to lower joint load. Causes: OA, fracture, injury.","Trendelenburg: weak gluteus medius (superior gluteal nerve injury, DDH, coxa vara, Perthes). Pelvis drops on the swing side during stance on the weak side; compensated by lurching the trunk over the weak hip. Bilateral weakness gives a waddling gait.","High-stepping (steppage): foot drop from weak dorsiflexors (common peroneal nerve palsy, L5 radiculopathy, CMT). Excess hip and knee flexion in swing to clear the toe, then foot slap or toe-first contact."]},
    {h:"Neurological gaits", p:["Hemiplegic (circumduction): stroke; extensor synergy of the leg with stiff knee, plantarflexed and inverted foot, so the leg swings out in an arc with hip hiking; arm held flexed, reduced arm swing.","Scissoring: spastic diplegic cerebral palsy; hip adductor and internal rotator spasticity make the knees cross in swing, narrow base, often with toe walking and crouch.","Festinating: Parkinson's disease; flexed posture, short shuffling steps that speed up as if chasing the centre of mass, reduced arm swing, freezing and turning en bloc.","Ataxic: cerebellar ataxia gives a wide-based, staggering, irregular gait not much helped by vision; sensory ataxia gives a high-stepping stamping gait with eyes on the feet, worse in the dark (Romberg positive)."]},
    {h:"Assessment", p:["Observational gait analysis by phase (initial contact to terminal swing), Trendelenburg test, MMT, Modified Ashworth Scale, Romberg, coordination tests.","Outcome measures: 10-metre walk test, TUG, 6-minute walk test, Dynamic Gait Index, footprint (paper) analysis of step and stride length."]},
    {h:"Physiotherapy management", p:["Antalgic: treat pain, cane in the opposite hand, graded weight-bearing. Trendelenburg: progressive hip abductor strengthening (side lying, side steps with band, 3 sets of 8-12), cane in the opposite hand.","Steppage: ankle-foot orthosis, dorsiflexor strengthening or FES of the peroneal nerve. Hemiplegic: task-specific and treadmill training, AFO, stretching of calf, hip and knee flexion practice.","Scissoring: adductor stretching, abduction positioning, orthoses, botulinum toxin with physiotherapy. Festinating: auditory or visual cues (metronome, floor lines), big amplitude stepping, treadmill training.","Ataxic: balance and coordination training, Frenkel's exercises for sensory ataxia, weighted walker, wider base for safety."]},
    {h:"Conclusion", p:["Recognising the gait pattern points to the underlying impairment. Effective management treats the impairment and uses aids, orthoses and repetitive gait practice to restore safe walking."]}
  ],
  tip:"Draw a back view of Trendelenburg (pelvis dropping on the swing side), a side view of steppage gait with high knee lift, and a front view of circumduction. Label the side of the lesion each time.",
  evidence:[["Treadmill training in Parkinson's disease","Improves gait speed and stride length","Moderate"],["Cueing training at home in Parkinson's disease","Small improvements in gait and freezing","Moderate"],["Cane in the hand opposite a weak or painful hip","Reduces hip abductor force","Moderate (biomechanical)"]],
  evidenceSource:"Mehrholz et al. Cochrane 2015; Nieuwboer et al. RESCUE trial 2007; Neumann",
  outcomes:[["10-metre walk test","Gait speed"],["Timed Up and Go","Functional mobility"],["Dynamic Gait Index","Gait under changing demands"],["Modified Ashworth Scale","Spasticity behind hemiplegic or scissoring gait"]],
  recent:["Gait speed is widely described as a functional vital sign (Fritz and Lusardi 2009) and is now the standard quick measure for all pathological gaits."],
  mnemonic:{word:"Pain, Hip, Foot, Brain", items:[["Pain","Antalgic"],["Hip","Trendelenburg (gluteus medius)"],["Foot","High-stepping (foot drop)"],["Brain","Hemiplegic, scissoring, festinating, ataxic"]], extra:"Trendelenburg: the pelvis drops on the SOUND (swing) side; the lesion is on the stance side."},
  example:"A 63-year-old farmer in Thanjavur had a left MCA stroke 3 months ago. He walks with the right leg swinging out in an arc, hip hiking and toe catching. He gets a right AFO, calf stretching and treadmill training with knee flexion practice.",
  flags:["Sudden new foot drop with back pain and saddle numbness: cauda equina, urgent referral","Sudden new gait change with headache or speech change: stroke","Frequent falls or freezing episodes: high fall risk, review safety"],
  viva:[["In Trendelenburg gait with a weak right gluteus medius, which side of the pelvis drops?","The left (swing) side, during stance on the right."],["What causes high-stepping gait?","Foot drop from weak dorsiflexors, commonly common peroneal nerve palsy or L5 root lesion."],["Which gait has short shuffling steps that speed up?","Festinating gait in Parkinson's disease."]],
  refs:[{b:"levangie",ch:"Gait"},{b:"osullivan",ch:"Examination of gait"},{c:"Perry J, Burnfield JM. Gait Analysis: Normal and Pathological Function. 2nd ed. Thorofare, NJ: SLACK; 2010.", q:"Perry Burnfield gait analysis normal pathological function"},{c:"Mehrholz J, Kugler J, Storch A, et al. Treadmill training for patients with Parkinson's disease. Cochrane Database Syst Rev. 2015;(8):CD007830.", q:"Mehrholz treadmill training Parkinson's disease Cochrane"}],
  keywords:"pathological gait abnormal gait patterns",
  mcq:[["High-stepping gait is most commonly due to:",["Gluteus medius weakness","Common peroneal nerve palsy","Hip adductor spasticity","Cerebellar lesion"],1,"Foot drop forces extra hip and knee flexion to clear the toes."],["Scissoring gait is typical of:",["Parkinson's disease","Spastic diplegic cerebral palsy","Tabes dorsalis","Hip osteoarthritis"],1,"Adductor spasticity makes the legs cross the midline."]]
}
]);
